/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $("#ipt_etfIsuSrtNm").bind("change", function() {
                $c.util.getComponent('ipt_etfIsuSrtCd').setValue("");
        });
        $("#ipt_reportNm").bind("change", function() {
                $c.util.getComponent('ipt_reportCd').setValue("");
        });
        $("#ipt_etfIsuSrtNm").bind("keypress", async function(e) {
                if (e.keyCode == 13) {
                    if ($c.util.getComponent('ipt_etfIsuSrtNm').getValue() !== $c.util.getComponent('ipt_etfIsuSrtCd').getValue()) {
                        $c.util.getComponent('ipt_etfIsuSrtCd').setValue("");
                    }
                    await scwin.fnSearchInit();
                }
        });
        $("#ipt_reportNm").bind("keypress", async function(e) {
                if (e.keyCode == 13) {
                    if ($c.util.getComponent('ipt_reportNm').getValue() !== $c.util.getComponent('ipt_reportTmp').getValue()) {
                        $c.util.getComponent('ipt_reportCd').setValue("");
                    }
                    await scwin.fnSearchInit();
                }
        });
        console.warn('[sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDatesOnlyPeriod(' + "1" + ')');
        await scwin.fnInit();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst00400.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst00400.onpageload' });
    }
};


